<script setup lang="ts">
defineProps<{ id: string; label: string; options: { value: string; label: string; disabled?: boolean }[]; modelValue?: string; placeholder?: string; helperText?: string; errorText?: string; disabled?: boolean; loading?: boolean; required?: boolean; dir?: 'rtl' | 'ltr' | 'auto' }>();
const emit = defineEmits<{ 'update:modelValue': [value: string] }>()
</script>
<template><div class="norato-select-group" :class="{ 'is-invalid': errorText, 'is-loading': loading }"><label class="norato-select__label" :for="id">{{ label }}<span v-if="required" aria-hidden="true"> *</span></label><select class="norato-select" :id="id" :dir="dir ?? 'rtl'" :value="modelValue" :disabled="disabled || loading" :required="required" :aria-invalid="errorText ? 'true' : undefined" :aria-describedby="[helperText && `${id}-helper`, errorText && `${id}-error`].filter(Boolean).join(' ') || undefined" @change="emit('update:modelValue', ($event.target as HTMLSelectElement).value)"><option v-if="placeholder" value="">{{ placeholder }}</option><option v-for="option in options" :key="option.value" :value="option.value" :disabled="option.disabled">{{ option.label }}</option></select><p v-if="helperText" :id="`${id}-helper`" class="norato-select__message">{{ helperText }}</p><p v-if="errorText" :id="`${id}-error`" class="norato-select__message norato-select__error" role="alert">{{ errorText }}</p></div></template>
